'use strict';
/* V2 shares the teaching engine and the editors with the classic laboratory. */
const GAME_STORE='traccia-er-v2-game';
let game={runs:{},best:{},log:[],sound:false,music:false,started:false};
try{const g=JSON.parse(localStorage.getItem(GAME_STORE)||'null');if(g&&typeof g==='object'){game={...game,...g,runs:g.runs||{},best:g.best||{},log:Array.isArray(g.log)?g.log.slice(-1200):[]};}}catch{storageOK=false;}
const runFor=()=>game.runs[current]||=(GameCore.fresh());
const totalXP=()=>GameCore.totalXP(game);
game.xpRecords=GameCore.xpRecords(game);
const totalStars=()=>Object.values(game.best).reduce((n,b)=>n+(Number(b.stars)||0),0);
const levels=['Apprendista archivista','Archivista','Maestro del catalogo'];
const rank=()=>levels[totalStars()>=14?2:totalStars()>=6?1:0];
let screen=game.started?'mission':'start',pageByStep={},notice='',bossCol='',musicTimer=null,audioContext=null,lastAction=Date.now();
const baseStageHTML=stageHTML,baseFeedbackHTML=feedbackHTML;
const missionNames=['Il catalogo dei libri','Lo schedario dei soci','La raccolta musicale','Il registro degli ordini','Il ricettario','L’emeroteca'];
const stageCommands=['Scegli cosa catalogare','Etichetta le schede','Associa le entità','Organizza le tabelle','Controlla l’archivio'];
const stageBriefs=['Riconosci entità, attributi ed esempi.','Scegli proprietà, chiave e tipo di identificazione.','Prima individua le associazioni, poi completa le due letture.','Ogni collegamento deve sopravvivere nelle tabelle.','Prova il tuo modello con dati concreti.'];
const faults=GameCore.faults;
function persistGame(){game.xpRecords=GameCore.xpRecords(game);try{localStorage.setItem(GAME_STORE,JSON.stringify(game));}catch{storageOK=false;}}
function logEvent(kind,details={}){game.log.push({at:new Date().toISOString(),mission:current,step:states[current].step+1,kind,...details});game.log=game.log.slice(-1200);persistGame();}
function tone(ok=true){if(!game.sound||document.hidden)return;try{audioContext||=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const t=audioContext.currentTime;[ok?440:165,ok?660:130,ok?880:110].forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t+i*.075);g.gain.linearRampToValueAtTime(.06,t+i*.075+.01);g.gain.exponentialRampToValueAtTime(.001,t+i*.075+.18);o.connect(g).connect(audioContext.destination);o.start(t+i*.075);o.stop(t+i*.075+.2);});}catch{}}
function setMusic(){clearInterval(musicTimer);musicTimer=null;if(!game.music||document.hidden)return;try{audioContext||=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();let beat=0;musicTimer=setInterval(()=>{if(document.hidden)return;const t=audioContext.currentTime,o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=[110,164.81,220,146.83,130.81,196,261.63,164.81][beat++%8];g.gain.setValueAtTime(.012,t);g.gain.exponentialRampToValueAtTime(.001,t+.55);o.connect(g).connect(audioContext.destination);o.start(t);o.stop(t+.6);},650);}catch{}}
document.addEventListener('visibilitychange',()=>{setMusic();lastAction=Date.now();});
function recordActive(){const delta=Date.now()-lastAction;if(!document.hidden&&delta<60000){const r=runFor();r.activeMs=(r.activeMs||0)+delta;}lastAction=Date.now();}
window.Game={
 beforeAction(a,c,s,el){recordActive();if(a==='check')logEvent('risposta',{answers:JSON.parse(JSON.stringify({entities:s.entities,attrs:s.attrs,keys:s.keys,identifications:s.identifications,relations:s.relations,tables:s.tables,quiz:s.quiz}))});},
 afterAction(a,c,s,el){const r=runFor();notice='';
  if(a==='view'){screen=el.dataset.view==='path'?'map':el.dataset.view==='rules'?'rules':'mission';}
  if(a==='case'){screen='mission';pageByStep={};game.started=true;}
  if(a==='check-associations'){pageByStep={};if(!s.associationsConfirmed)GameCore.verify(r,'association-discovery',false,false);tone(s.associationsConfirmed);logEvent('verifica-associazioni',{ok:s.associationsConfirmed,choices:[...s.associationChoices],issues:feedback?.issues||[]});}
  if(a==='association-back')pageByStep={};
  if(a==='check'){const gain=GameCore.verify(r,'step-'+s.step,feedback.ok,s.assisted.includes(s.step));notice=feedback.ok?(gain?'+'+gain+' XP · schede in ordine':'Passaggio verificato'):(r.energy?'Puoi riprovare. Il lavoro resta al suo posto.':'Archi ha la batteria scarica: apri un aiuto per ricaricarlo.');tone(feedback.ok);logEvent('verifica',{ok:feedback.ok,issues:feedback.issues,gain});}
  if(a==='hint'||a==='solve'){r.hints++;if(!r.energy)r.energy=3;logEvent(a==='hint'?'indizio':'soluzione');}
  if(a==='next'){pageByStep={};if(s.step===4&&s.completed&&!r.bossPassed){s.completed=false;screen='boss';initBoss();}else if(s.completed){screen='complete';}}
  if(a==='review'){screen='mission';}
  if(a==='previous'||a==='step'){pageByStep={};}
  if(a==='confirm-reset'){game.runs[current]=GameCore.fresh();pageByStep={};screen='mission';reviewing=false;}
  if(a==='table'&&s.tables[el.dataset.name])pageByStep[3]=Object.keys(s.tables).indexOf(el.dataset.name);
  persistGame();
 }
};
function initBoss(){const r=runFor();if(r.boss)return;const c=cases.find(c=>c.id===current),s=ER.empty(c);ER.solve(c,s,3);const f=faults[current];s.tables[f.table][f.col][f.prop]=f.bad;r.boss=s;bossCol='';logEvent('guasto-aperto');}
function starString(n){return '★'.repeat(n)+'☆'.repeat(3-n);}
function hud(){const r=runFor();return `<header class="game-header"><button data-game="welcome" class="game-brand" aria-label="Incontra Archi">TRACCIA <b>ARCHIVIO <small>V2</small></b></button><div class="hud-score"><strong aria-live="polite" aria-atomic="true">${totalXP()} XP <small>totali</small></strong><span>${totalStars()} / 18 ★ · record</span></div><button class="audio-btn" data-game="sound" aria-label="${game.sound?'Disattiva':'Attiva'} suoni" aria-pressed="${game.sound}">${game.sound?'♫':'♪'}<span>${game.sound?'ON':'OFF'}</span></button></header>`;}
function nav(){return `<nav class="game-nav" aria-label="Navigazione"><button data-game="map" ${screen==='map'?'aria-current="page"':''}>Reparti</button><button data-game="mission" ${screen==='mission'||screen==='boss'?'aria-current="page"':''}>Incarico</button><button data-game="rules" ${screen==='rules'?'aria-current="page"':''}>Manuale</button><button data-game="log" ${screen==='log'?'aria-current="page"':''}>Registro</button></nav>`;}
function coach(message){return `<div class="coach"><img src="assets/archi.webp" alt="" width="54" height="62"><p><strong class="coach-name">Archi</strong>${esc(message)}</p></div>`;}
function pager(index,total,names){if(total<2)return '';return `<div class="module-tabs" aria-label="Elementi del passaggio">${names.map((n,i)=>`<button data-game="page" data-page="${i}" aria-pressed="${index===i}">${esc(n)}</button>`).join('')}</div>`;}
stageHTML=function(c,s){const html=baseStageHTML(c,s);if(s.step===0||s.step===2&&!s.associationsConfirmed)return html;const temp=document.createElement('div');temp.innerHTML=html;const selector={1:'.entity-editor',2:'.relation-editor',3:'.table-editor',4:'.question'}[s.step];const blocks=[...temp.querySelectorAll(selector)];const index=Math.max(0,Math.min(pageByStep[s.step]||0,blocks.length-1));const names=blocks.map((b,i)=>s.step===4?'Test '+(i+1):b.querySelector('h3')?.textContent||String(i+1));const tabs=pager(index,blocks.length,names)+(blocks.length>1?'<p class="small-note pager-note">Completa tutte le schede, poi verifica le schede.</p>':'');blocks.forEach((b,i)=>{if(i!==index)b.remove();});return tabs+temp.innerHTML;};
function followingPage(c,s){if(s.step===2&&!s.associationsConfirmed)return null;const count=s.step===1?c.entities.length:s.step===2?c.relations.length:s.step===4?c.questions.length:0;const index=pageByStep[s.step]||0;return !s.passed.includes(s.step)&&index<count-1?index+1:null;}
function playHTML(c,s){const r=runFor();return `<section class="mission-title"><div><span class="eyebrow">INCARICO ${cases.indexOf(c)+1} / 6</span><h1>${missionNames[cases.indexOf(c)]}</h1></div></section><div class="energy-row"><span class="energy" aria-label="Batteria ${r.energy} di 3">${[0,1,2].map(i=>`<i class="${i<r.energy?'charged':''}"></i>`).join('')}<span>Batteria ${r.energy}/3</span></span><span>${r.combo>=2?'Serie ×'+r.combo:'Un passaggio alla volta'}</span></div><div class="game-steps" aria-label="Passaggi dell’incarico">${stageNames.map((n,i)=>`<button data-action="step" data-step="${i}" ${i>s.passed.length?'disabled':''} ${s.step===i?'aria-current="step"':''} class="${s.passed.includes(i)?'charged':''}" aria-label="${i+1}. ${n}"><b>${s.passed.includes(i)?'✓':i+1}</b><span>${n}</span></button>`).join('')}<span class="boss-mark" title="Controllo finale">⚡</span></div><div class="game-work"><section><header class="command"><h2>${stageCommands[s.step]}</h2><p>${stageBriefs[s.step]}</p></header><details class="brief"><summary>Traccia · ${esc(c.short)}</summary><p class="brief-body">${esc(c.prompt)}</p></details>${s.step===0?coach(c.prompt.split('. ').slice(0,2).join('. ')+'.'):''}${stageHTML(c,s)}${baseFeedbackHTML()}${notice?`<p class="reward" role="status">${esc(notice)}</p>`:''}<div class="help-row"><button class="text-button" data-action="hint">${s.hints[s.step]?'Un altro consiglio':'Chiedi ad Archi'}</button>${s.hints[s.step]>=2?'<button class="text-button" data-action="solve">Mostra il passaggio</button>':''}<button class="text-button" data-action="model-toggle" aria-expanded="${showModel}">${showModel?'Chiudi':'Apri'} schema</button></div>${s.hints[s.step]?coach(hintFor(c,s)):''}${s.assisted.includes(s.step)?'<p class="small-note">Con soluzione: completa l’incarico, poi riprovala per migliorare.</p>':''}</section><aside class="aside ${!showModel?'mobile-hidden':''}" id="model-panel">${modelHTML(c,s)}</aside></div>`;}
function startHTML(){return `<section class="start-screen"><div class="start-art"><img src="assets/archi.webp" alt="Archi, il robot archivista" width="155" height="180"><div><p class="eyebrow">ARCHI HA BISOGNO DI TE</p><h1>Un archivio.<br>Mille cose da ordinare.</h1><p>6 reparti da riordinare.<br>Un robot che conta su di te.</p></div></div><div class="start-panel"><h2>«Ciao, sono Archi!»</h2><p>Ho trovato libri, tessere e documenti tutti mescolati. Mi aiuti a catalogarli? Scegli le entità, assegna le chiavi e rimetti in ordine i collegamenti.</p><button class="primary" data-game="start">${game.started?'Riprendi l’incarico':'Aiuta Archi: primo incarico'}</button><div class="reward-rules"><span>★ Completa</span><span>★★ Senza soluzioni</span><span>★★★ Senza errori o aiuti</span></div></div><p class="small-note">Nessun conto alla rovescia. Gli aiuti sono sempre disponibili. I progressi restano nel browser.</p><a href="../" class="classic-link">Preferisci il laboratorio classico?</a></section>`;}
function mapHTML(){return `<div class="map-title"><span class="eyebrow">${rank()}</span><h1>I reparti dell’archivio</h1><p>Aiuta Archi a sistemare un reparto alla volta. Puoi riprovare ogni incarico per migliorare il record.</p></div><div class="mission-map">${cases.map((c,i)=>{const b=game.best[c.id],s=states[c.id];return `<article class="mission-card ${c.id===current?'current':''}"><div class="mission-number">${String(i+1).padStart(2,'0')}</div><div><div class="map-meta"><span>Reparto ${i+1}</span><span class="stars" aria-label="${b?.stars||0} stelle">${starString(b?.stars||0)}</span></div><h2>${missionNames[i]}</h2><p>${b?b.points+' XP':s.passed.length+'/5 passaggi'}</p><button class="secondary" data-action="case" data-id="${c.id}">${b?'Rivedi / migliora':s.passed.length?'Continua':'Gioca'}</button></div></article>`;}).join('')}</div><p class="small-note map-note">I reparti sono tutti accessibili, anche per il lavoro in classe. Le stelle premiano precisione e autonomia; gli XP totali sommano il miglior punteggio raggiunto in ogni reparto, anche prima di completarlo. Riprovare conserva gli XP e li aumenta solo se migliori.</p>`;}
function bossHTML(c){initBoss();const r=runFor(),f=faults[current],cols=r.boss.tables[f.table];const selected=cols[bossCol];return `<section class="boss-intro"><span class="eyebrow">ULTIMO CONTROLLO · ${cases.indexOf(c)+1}/6</span><h1>C’è una scheda fuori posto.</h1>${coach(f.story)}<p>Archi ha trovato un errore nel catalogo. Tocca una colonna e correggi il vincolo sbagliato.</p></section><div class="boss-board"><div class="relation-scroll" tabindex="0" role="region" aria-label="Schema da riparare"><table class="relational-table"><caption>${esc(f.table)}</caption><thead><tr>${Object.keys(cols).map(n=>`<th><button data-game="boss-col" data-col="${n}" aria-pressed="${n===bossCol}">${esc(n)}</button></th>`).join('')}</tr></thead><tbody><tr>${Object.values(cols).map(col=>`<td><strong class="key">${[col.pk?'PK':'',col.fk?'FK':'',col.unique?'UNIQUE':''].filter(Boolean).join(' · ')||'—'}</strong>${col.fk?`<small>${esc(col.fk)}</small>`:''}</td>`).join('')}</tr></tbody></table></div>${selected?`<div class="repair-tools"><h2>${esc(bossCol)}</h2><div class="repair-flags">${['pk','unique'].map(k=>`<button data-game="boss-flag" data-prop="${k}" aria-pressed="${!!selected[k]}">${k.toUpperCase()} ${selected[k]?'attivo':'assente'}</button>`).join('')}</div><label for="boss-fk">Destinazione FK</label><select id="boss-fk" data-game="boss-fk"><option value="">Nessuna FK</option>${c.tables.flatMap(t=>t.cols.filter(x=>x.pk).map(x=>t.name+'.'+x.name)).map(v=>`<option value="${v}" ${selected.fk===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`:'<div class="repair-empty">Scegli un’intestazione per correggere la scheda.</div>'}</div>${notice?`<div class="feedback" role="status">${esc(notice)}</div>`:''}<div class="help-row"><button class="text-button" data-game="boss-hint">Chiedi ad Archi</button><button class="text-button" data-game="boss-reset">Ripristina la scheda</button></div>${r.bossHint?coach(f.hint):''}`;}
function doneHTML(c){const r=runFor(),b=game.best[current],i=cases.indexOf(c);return `<section class="victory"><div class="stars big-stars">${starString(GameCore.stars(r,states[current].assisted.length))}</div><span class="eyebrow">REPARTO RIORDINATO</span><h1>${missionNames[i]}</h1><p>«Tutto al suo posto. Grazie!» — Archi</p><div class="result-grid"><div><b>${r.points}</b><span>XP dell’incarico</span></div><div><b>${r.errors}</b><span>verifiche da correggere</span></div><div><b>${r.bestCombo}</b><span>serie migliore</span></div></div><div class="rule-summary"><p>${esc(c.rule)}</p></div><p class="small-note">Record ${b?.points||0} XP · ${starString(b?.stars||0)}. Per tre stelle: nessun errore, indizio o soluzione.</p><button class="primary" data-action="case" data-id="${cases[(i+1)%cases.length].id}">${i<5?'Incarico successivo: '+(i+2):'Ricomincia dal primo reparto'}</button><div class="victory-actions"><button class="secondary" data-action="review">Rivedi le tabelle</button><button class="secondary" data-action="reset">Migliora il record</button></div><button class="text-button" data-game="download">Scarica il diario</button></section>`;}
function diaryHTML(){return `<section class="diary"><span class="eyebrow">${rank()}</span><h1>Registro dell’archivista</h1><p>Le schede controllate, gli errori corretti e gli aiuti di Archi. Puoi consegnarlo al docente.</p><div class="result-grid"><div><b>${totalXP()}</b><span>XP totali</span></div><div><b>${totalStars()}/18</b><span>stelle</span></div><div><b>${Object.keys(game.best).length}/6</b><span>incarichi</span></div></div><button class="primary" data-game="download">Scarica il diario JSON</button><button class="secondary" data-game="report">Scarica il riepilogo HTML</button><label class="music-setting"><input type="checkbox" data-game="music" ${game.music?'checked':''}>Musica di sottofondo</label><p class="small-note">File locali, nessun invio automatico. Sono registrati gli ultimi 1200 eventi; il diario è modificabile e non certifica un voto. I progressi del laboratorio classico rimangono separati.</p><div class="event-list">${game.log.slice(-12).reverse().map(e=>`<p><b>${esc(e.kind)}</b> · ${esc(cases.find(c=>c.id===e.mission)?.short)}${typeof e.ok==='boolean'?' · '+(e.ok?'corretto':'da rivedere'):''}</p>`).join('')||'<p>Nessun evento: avvia il primo incarico.</p>'}</div><a class="classic-link" href="../">Apri il laboratorio classico</a></section>`;}
render=function(){const c=cases.find(c=>c.id===current),s=states[current],r=runFor();if(screen==='mission'&&s.completed&&!reviewing)screen=r.bossPassed?'complete':'boss';if(screen==='complete'&&!r.bossPassed)screen='mission';document.title=(screen==='mission'?missionNames[cases.indexOf(c)]:'Archivio in ordine')+' · Traccia V2';document.body.classList.toggle('celebrating',screen==='complete');document.getElementById('app').innerHTML=hud()+nav()+(!storageOK?'<div class="storage-warning">Salvataggio non disponibile: lascia aperta questa pagina e scarica il diario prima di uscire.</div>':'')+`<main id="workspace" class="game-shell" tabindex="-1">${screen==='start'?startHTML():screen==='map'?mapHTML():screen==='rules'?rulesHTML():screen==='log'?diaryHTML():screen==='boss'?bossHTML(c):screen==='complete'?doneHTML(c):playHTML(c,s)}</main>`+(screen==='mission'?`<div class="footer-action"><div class="action-inner"><button class="back" data-action="previous" ${s.step===0?'disabled':''}>Indietro</button><span class="action-info">Passaggio ${s.step+1}/5</span>${followingPage(c,s)!==null?`<button class="primary" data-game="page" data-page="${followingPage(c,s)}">Scheda successiva</button>`:`<button class="primary" data-action="${s.step===2&&!s.associationsConfirmed?'check-associations':s.passed.includes(s.step)?'next':'check'}">${s.step===2&&!s.associationsConfirmed?'Verifica le associazioni':s.passed.includes(s.step)?(s.step===4?'Controlla l’ultima scheda':'Passaggio successivo'):'Verifica le schede'}</button>`}</div></div>`:screen==='boss'?'<div class="footer-action"><div class="action-inner"><button class="back" data-game="inspect">Rivedi lo schema</button><button class="primary" data-game="boss-check">Verifica la correzione</button></div></div>':'')+(dialog?dialogHTML():'');};
function download(content,name,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function report(){return {app:'Traccia V2 · Archivio in ordine',version:2,exportedAt:new Date().toISOString(),xp:totalXP(),stars:totalStars(),best:game.best,runs:game.runs,learning:states,events:game.log,note:'Dati locali modificabili. Non è una certificazione di valutazione.'};}
function gameAction(event){const el=event.target.closest('[data-game]');if(!el)return;const action=el.dataset.game;if((event.type==='change')!==['boss-fk','music'].includes(action))return;recordActive();const c=cases.find(c=>c.id===current),s=states[current],r=runFor();let top=false;notice='';switch(action){
 case 'welcome':screen='start';top=true;break;
 case 'start':game.started=true;screen='mission';logEvent('missione-avviata');tone();top=true;break;
 case 'map':screen='map';top=true;break;
 case 'rules':screen='rules';top=true;break;
 case 'log':screen='log';top=true;break;
 case 'mission':screen='mission';top=true;break;
 case 'sound':game.sound=!game.sound;tone();break;
 case 'music':game.music=el.checked;setMusic();break;
 case 'page':pageByStep[s.step]=Number(el.dataset.page);break;
 case 'boss-col':bossCol=el.dataset.col;break;
 case 'boss-flag':if(r.boss?.tables[faults[current].table]?.[bossCol]){const col=r.boss.tables[faults[current].table][bossCol];col[el.dataset.prop]=!col[el.dataset.prop];logEvent('riparazione',{column:bossCol,property:el.dataset.prop,value:col[el.dataset.prop]});}break;
 case 'boss-fk':r.boss.tables[faults[current].table][bossCol].fk=el.value;logEvent('riparazione',{column:bossCol,property:'fk',value:el.value});break;
 case 'boss-reset':r.boss=null;initBoss();break;
 case 'boss-hint':r.hints++;r.bossHint=true;logEvent('indizio-guasto');break;
 case 'inspect':screen='mission';reviewing=true;s.step=3;showModel=true;modelMode='tables';top=true;break;
 case 'boss-check':{const result=ER.check(c,r.boss,3);const gain=GameCore.verify(r,'boss',result.ok,false);tone(result.ok);logEvent('collaudo-guasto',{ok:result.ok,issues:result.issues,gain,table:r.boss.tables[faults[current].table]});if(result.ok){r.bossPassed=true;s.completed=true;game.best[current]=GameCore.finish(r,game.best[current],s.assisted.length);screen='complete';reviewing=false;top=true;}else notice='La scheda ha ancora un errore.  '+result.issues.slice(0,2).join(' ');break;}
 case 'download':download(JSON.stringify(report(),null,2),'Traccia-V2-diario.json','application/json');break;
 case 'report':{const body=`<!doctype html><html lang="it"><meta charset="utf-8"><title>Diario Traccia V2</title><style>body{font:17px/1.6 system-ui;max-width:850px;margin:30px auto;padding:20px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #aaa;padding:8px}h1{color:#194c59}</style><h1>Traccia V2 · Registro dell’archivista</h1><p>${esc(new Date().toLocaleString('it-IT'))} · ${totalXP()} XP · ${totalStars()}/18 stelle</p><table><tr><th>Incarico</th><th>Record</th><th>Stelle</th></tr>${cases.map(c=>`<tr><td>${esc(c.title)}</td><td>${game.best[c.id]?.points||0}</td><td>${game.best[c.id]?.stars||0}/3</td></tr>`).join('')}</table><h2>Verifiche e aiuti</h2>${game.log.filter(e=>['verifica','collaudo-guasto','indizio','soluzione'].includes(e.kind)).map(e=>`<p>${esc(e.at)} · ${esc(e.mission)} · ${esc(e.kind)}${typeof e.ok==='boolean'?e.ok?' · corretto':' · da rivedere':''}${e.issues?.length?'<br>'+e.issues.map(esc).join('<br>'):''}</p>`).join('')}<p>Dati locali modificabili, non una certificazione di valutazione. Il JSON contiene anche le scelte effettuate.</p></html>`;download(body,'Traccia-V2-riepilogo.html','text/html');break;}
 }
 save();persistGame();render();if(top)goTop();else if(el.id)document.getElementById(el.id)?.focus({preventScroll:true});else [...document.querySelectorAll('[data-game]')].find(b=>b.dataset.game===action&&Object.entries(el.dataset).every(([k,v])=>b.dataset[k]===v))?.focus({preventScroll:true});}
document.addEventListener('click',gameAction);document.addEventListener('change',gameAction);
render();
